#ifndef OVERLAY_H
#define OVERLAY_H

#include "types.h"
#include "overlay_ids.h"

// Overlays are separately linked code blobs, ZX02-compressed on cart, that
// are decompressed to __overlay_start (the end of resident RAM) one at a time.
// Each overlay is built from game/<name>/*.cpp (OVERLAYS in the Makefile) and
// links against the resident, so it can call any sys:: function and read any
// resident global. overlay_ids.h is generated by pack_lynx_cart.py from the
// OVERLAYS list.
//
// Every overlay defines ovl_Main, which runs until the overlay is done and
// returns the id of the overlay to run next. The overlay's .bss and zero page
// are zeroed before ovl_Main runs, and its .data is reloaded from cart, so
// overlay globals start fresh on every load. State that must survive an
// overlay switch lives in resident globals.
extern "C" u8 ovl_Main(void);

namespace sys::overlay {

// Load overlay `id` and run its ovl_Main. Returns ovl_Main's result.
u8 Run(u8 id);

}

#endif
